<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Sorting Algorithm Visualizer</title>
    <style>
        body {
            background-color: #121212;
            color: #e0e0e0;
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
            overflow: hidden;
        }

        #controls {
            margin-bottom: 30px;
        }

        button {
            background-color: #2c2c2c;
            color: #ffffff;
            border: 1px solid #444;
            padding: 10px 20px;
            margin: 0 5px;
            cursor: pointer;
            font-size: 14px;
            font-weight: 600;
            text-transform: uppercase;
            border-radius: 4px;
            transition: all 0.2s ease;
        }

        button:hover {
            background-color: #3d3d3d;
            border-color: #bb86fc;
        }

        button:active {
            transform: translateY(1px);
        }

        button:disabled {
            opacity: 0.4;
            cursor: not-allowed;
        }

        #bars {
            display: flex;
            align-items: flex-end;
            height: 350px;
            width: 90vw;
            max-width: 800px;
            gap: 4px;
            padding: 10px;
            border-bottom: 2px solid #333;
        }

        .bar {
            flex: 1;
            background-color: #bb86fc;
            border-radius: 2px 2px 0 0;
            transition: height 0.15s ease, background-color 0.2s ease;
        }
    </style>
</head>
<body>

<div id="controls">
    <button id="sort">Sort</button>
    <button id="shuffle">Shuffle</button>
    <button id="reset">Reset</button>
</div>

<div id="bars"></div>

<script>
    // Application State
    const initialArray = [45, 82, 12, 34, 67, 90, 23, 56, 78, 5, 44, 62];
    let currentArray = [...initialArray];
    let i = 0;
    let j = 0;
    let isDone = false;
    let isSorting = false;

    // DOM Elements
    const barsContainer = document.getElementById('bars');
    const sortBtn = document.getElementById('sort');
    const shuffleBtn = document.getElementById('shuffle');
    const resetBtn = document.getElementById('reset');

    /**
     * Renders the array as vertical bars in the DOM.
     */
    function render() {
        barsContainer.innerHTML = '';
        currentArray.forEach(val => {
            const bar = document.createElement('div');
            bar.className = 'bar';
            // Map value (assuming 0-100 range) to percentage height
            bar.style.height = `${val}%`;
            barsContainer.appendChild(bar);
        });
    }

    /**
     * Programmatic API required for grading.
     */
    window.viz = {
        array: () => [...currentArray],
        setArray: (a) => {
            currentArray = [...a];
            // Reset sort state machine when array changes
            i = 0;
            j = 0;
            isDone = false;
            render();
        },
        sortStep: () => {
            if (isDone) return true;

            const n = currentArray.length;
            if (n <= 1) {
                isDone = true;
                return true;
            }

            // Performs exactly one comparison and potential swap (Bubble Sort step)
            if (currentArray[j] > currentArray[j + 1]) {
                const temp = currentArray[j];
                currentArray[j] = currentArray[j + 1];
                currentArray[j + 1] = temp;
                render(); // Update visuals to show the swap
            }

            j++;
            // Check if the inner pass of Bubble Sort is complete
            if (j >= n - 1 - i) {
                j = 0;
                i++;
            }

            // Check if the outer loop is complete
            if (i >= n - 1) {
                isDone = true;
                return true;
            }

            return false;
        },
        sorted: () => {
            for (let k = 0; k < currentArray.length - 1; k++) {
                if (currentArray[k] > currentArray[k + 1]) return false;
            }
            return true;
        }
    };

    /**
     * Drives the animation loop for sorting.
     */
    async function runSort() {
        if (isSorting) return;
        isSorting = true;

        // Disable buttons to prevent user from corrupting state during sort
        sortBtn.disabled = true;
        shuffleBtn.disabled = true;
        resetBtn.disabled = true;

        try {
            while (!window.viz.sortStep()) {
                // Small delay for visual animation effect
                await new Promise(resolve => setTimeout(resolve, 40));
            }
        } catch (e) {
            console.error("Sort interrupted", e);
        } finally {
            isSorting = false;
            sortBtn.disabled = false;
            shuffleBtn.disabled = false;
            resetBtn.disabled = false;
        }
    }

    // Event Listeners
    sortBtn.addEventListener('click', runSort);

    shuffleBtn.addEventListener('click', () => {
        const newArr = currentArray.map(() => Math.floor(Math.random() * 90) + 5);
        window.viz.setArray(newArr);
    });

    resetBtn.addEventListener('click', () => {
        window.viz.setArray(initialArray);
    });

    // Initialize the view
    render();

</script>
</body>
</html>
